import {chooseAmbition} from './legacy.js?v=3.2.0';
import {ambitionPanel,stakesPanel,highlightsPanel,reviewPanel,legacyPanel} from './legacy-view.js?v=3.2.0';
import {DOMAINS,domainOf,costDetails} from './progression.js?v=3.2.0';
import {lifeAction,netWorth} from './life.js?v=3.2.0';
import {tendencies} from './match.js?v=3.2.0';
import {LEAGUES,REFERENCE,leagueDef} from './leagues.js?v=3.2.0';
import {KEYS,LABELS,GROUPS,STYLES,BADGES,TECHNIQUES,LEVELS,CFG,VERSION} from './config.js?v=3.2.0';
import {defaultBuild,buildCaps,limits,potentialCost,createGame,hero,team,overall,next,upgrade,upgradeCost,badgeLevel,learn,equip,continueMatch,grade,standings,sign,requestTrade,log,activeLeague,competition,playerGames,decide,scouting,syncLeague} from './engine.js?v=3.2.0';
import {save,load,parseSave} from './storage.js?v=3.2.0';
let archivePrefix=[];
let s=null,tab='home',sub='attrs',build=defaultBuild(),step=0,busy=false,progress=0,notice='',worker=null,leagueView='Classement',selectedTeam=null,installPrompt=null,creation=false,acting=false,archiveSeason=null,leagueSelection=null;
const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Math.round(n).toLocaleString('fr-FR'),btn=(text,action,cls='',disabled=false)=>`<button class="${cls}" data-action="${action}" ${disabled?'disabled':''}>${text}</button>`,meter=(v,max=100)=>`<div class="meter"><i style="width:${Math.min(100,Math.max(0,v/max*100))}%"></i></div>`,pill=t=>`<span class="pill">${esc(t)}</span>`;
function toast(t){$('toast').textContent=t;setTimeout(()=>{$('toast').textContent=''},4000)}
async function persist(){try{await save(s);notice='Sauvegardé sur cet appareil'}catch{notice='Sauvegarde impossible : exportez votre partie';toast(notice)}}
const date=()=>new Date(Date.UTC(REFERENCE.baseYear,8,1+s.day)).toLocaleDateString('fr-FR',{day:'numeric',month:'long',year:'numeric'});
function header(){return `<header><a class="brand" href="#" aria-label="HOOP LEGACY accueil"><span class="logo">H<span>•</span>L</span> HOOP <b>LEGACY</b></a><span class="edition">WORLD TOUR / ${s?'S'+s.season:'2026'}</span>${s?`<span class="save-dot" title="${esc(notice)}">${notice.includes('impossible')?'!':'✓'} <span>${esc(notice||'Sauvegarde locale')}</span></span>`:''}${s?btn('☰','tab:more','small settings-button'):''}</header>`}
function render(){if(!s||creation){renderCreation();return}let p=hero(s);$('app').innerHTML=header()+`<div class="shell"><aside><p class="eyebrow">VOTRE CARRIÈRE</p><h2>${esc(p.name)}</h2><p class="muted">${esc(team(s).name)}</p><div class="profile-number">${overall(p)}<small>NOTE GÉNÉRALE</small></div>${nav(false)}<div class="aside-foot">${pill(activeLeague(s).name)}<p>${s.career.stage==='highschool'?'Parcours lycée':s.career.stage==='college'?'Parcours universitaire':'Carrière professionnelle'} · S${s.season}</p><p class="muted">${date()}</p></div></aside><main><div class="page-top"><div><p class="eyebrow">SAISON ${String(s.season).padStart(2,'0')} / ${esc(s.phase).toUpperCase()}</p><h1>${{home:'Le prochain chapitre.',player:'Construisez votre jeu.',career:'Votre trajectoire.',league:'La ligue en mouvement.',life:'Une vie autour du basket.',more:'Réglages & sauvegardes.'}[tab]}</h1></div><span class="date">${date()}</span></div>${s.pending?pending():''}${busy?`<section class="panel"><h3>Simulation en cours · ${Math.round(progress*100)} %</h3>${meter(progress,1)}${btn('Arrêter à la prochaine période','stop','secondary')}</section>`:''}${({home:home,player:player,career:career,league:league,life:life,more:more}[tab])()}</main></div>${nav(true)}`;bind()}
function nav(mobile){return `<nav class="${mobile?'bottom-nav':'side-nav'}">${[['home','⌂','Aujourd’hui'],['player','◉','Joueur'],['career','↗','Carrière'],['life','♡','Vie'],['league','▤','Monde']].map(([id,icon,label])=>`<button data-action="tab:${id}" class="${tab===id?'active':''}"><span>${icon}</span>${label}</button>`).join('')}</nav>`}
function pathway(){let stage=s.career.stage;return `<section class="pathway">${[['highschool','01','Lycée'],['college','02','Université'],['pro','03','Carrière pro']].map(([id,n,t])=>`<div class="${stage===id?'current':''}"><span>${n}</span><b>${t}</b><small>${id==='highschool'?s.career.hsYears+' saison(s)':id==='college'?s.career.collegeYears+' saison(s)':s.draftResult?.rank?'Draft n° '+s.draftResult.rank:'NBA & monde'}</small></div>`).join('')}</section>`}
function home(){let p=hero(s),def=activeLeague(s),g=playerGames(s).find(g=>!g.result),st=p.season,scan=s.lastSeasonScouting||scouting(s);return `${pathway()}<section class="hero-panel"><div><div class="eyebrow">${esc(team(s).name)} <span class="orange">/ ${esc(def.name)}</span></div><h2>${esc(p.name)}<span>${esc(p.pos)} · ${p.age} ans · ${esc(s.role)}</span></h2><div class="hero-stats"><div><strong>${overall(p)}</strong><small>GÉNÉRAL</small></div><div><strong>${st.gp?(st.pts/st.gp).toFixed(1):'—'}</strong><small>POINTS / MATCH</small></div><div><strong>+${s.development.gained}</strong><small>ATTRIBUTS DÉVELOPPÉS</small></div></div></div><div class="court" aria-label="Terrain schématique"><div class="court-center"></div><div class="paint"></div><div class="arc"></div><span class="court-player">07</span><span class="court-label">${esc(p.style).toUpperCase()}</span></div></section>${s.match?liveMatch():`<section class="next-event"><div><p class="eyebrow">${s.retired?'CARRIÈRE TERMINÉE':g?esc(leagueDef(g.league).name):'INTERSAISON & ORIENTATION'}</p><h3>${s.retired?'Votre histoire reste ici.':s.pending?'Une décision vous attend':g?esc(team(s,g.home===s.team?g.away:g.home).name):'La saison touche à sa fin'}</h3><p class="muted">${s.round} / ${def.games} matchs de saison régulière · ${s.minutes} minutes prévues${g?' · '+(g.stage==='regular'?'Championnat':g.stage==='playin'?'Play-in':'Playoffs'):''}</p>${stakesPanel(s,g)}</div><div class="advance"><label class="sr" for="advance-size">Avancer jusqu’à</label><select id="advance-size"><option value="1">Prochain événement</option><option value="match">Prochain match</option><option value="2">Une semaine</option><option value="10">Dix étapes</option><option value="40">Fin de saison / décision</option></select>${btn(s.retired?'Carrière terminée':'Avancer →','advance','primary',busy||!!s.pending||s.retired)}</div></section>`}${highlightsPanel(s)}${s.lastMatch&&!s.match?summary():''}${ambitionPanel(s)}${reviewPanel(s)}<div class="metrics home-metrics"><article><span>ÉNERGIE</span><strong>${Math.round(100-p.fatigue)}<small>/100</small></strong>${meter(100-p.fatigue)}<p>${p.injury?`Blessure · ${p.injury} jours`:'Disponible'}</p></article><article><span>CONFIANCE DU COACH</span><strong>${Math.round(s.trust)}<small>/100</small></strong>${meter(s.trust)}<p>${s.role} · ${s.minutes} min</p></article><article><span>XP DISPONIBLE</span><strong>${Math.round(Object.values(s.development.xp).reduce((a,b)=>a+b,0))}<small>XP</small></strong><p>6 domaines · allocation ${s.auto?'automatique':'manuelle'}</p></article></div><details class="panel home-journal"><summary>Journal et parcours</summary><div class="two-col"><section class="panel"><div class="section-title"><h3>Journal de carrière</h3><span class="muted">${s.teams.length} clubs et programmes</span></div><div class="timeline">${s.log.slice(0,8).map(e=>`<article><span class="timeline-date">S${e.season} · J${e.day-(e.season-1)*365}</span><div><h4>${esc(e.title)}</h4><p>${esc(e.text)}</p></div></article>`).join('')}</div></section><section class="panel"><p class="eyebrow">${s.career.stage==='highschool'?'OBJECTIF : UNE UNIVERSITÉ':s.career.stage==='college'?'LA NBA EN LIGNE DE MIRE':'VOTRE PROCHAIN PALIER'}</p><h3>${s.career.stage==='highschool'?'Se faire recruter.':s.career.stage==='college'?esc(scan.projection):'Développer votre impact.'}</h3><p class="muted">${s.career.stage==='highschool'?'Vos résultats scolaires, vos performances et votre efficacité déterminent les programmes intéressés.':s.career.stage==='college'?'Après chaque saison universitaire : rester pour progresser ou se déclarer à la draft. Une projection n’est jamais une garantie.':'Les propositions internationales tiennent compte de votre niveau et des besoins de chaque club.'}</p>${s.career.stage!=='pro'?`<p>Études : <b>${Math.round(s.career.academics)}/100</b> · Exposition : <b>${Math.round(s.career.exposure)}/100</b></p>`:''}<div class="focus-stat"><strong>${p.attrs[s.training]}</strong><span>/ ${p.caps[s.training]}<small>${LABELS[s.training]}</small></span></div><p class="muted">XP issue de vos performances et de l’entraînement. Les coûts augmentent aux niveaux élevés, sans plafond de build.</p>${btn('Mon développement ↗','tab:player','secondary')}</section></div></details>`}
function pending(){let e=s.pending;return `<section class="decision"><p class="eyebrow">DÉCISION · LA SIMULATION EST EN PAUSE</p><h2>${esc(e.title)}</h2><p>${esc(e.text)}</p>${e.type==='draft-choice'?`<div class="button-row">${btn('Me déclarer à la draft NBA','decision:draft','primary')}${s.career.collegeYears<4?btn('Rester une saison à l’université','decision:stay','secondary'):''}</div>`:e.type==='contract'?`<div class="offers">${s.offers.map((o,i)=>`<article><p class="eyebrow">${esc(leagueDef(o.league).name)}</p><h3>${esc(team(s,o.team).name)}</h3><strong>${o.academic?'Place au programme':fmt(o.salary)+' € / an'}</strong><p>${o.role} · ${o.minutes} min prévues<br>${o.academic?'Une saison universitaire':o.years+' ans'}</p><p class="muted">${esc(o.reason||'')}</p>${btn(o.academic?'Choisir cette université':'Signer ce contrat','sign:'+i,'primary')}</article>`).join('')}</div>${e.canDecline?btn('Rester dans mon club','decision:decline','secondary'):''}`:`<div class="offers">${(e.choices||[]).map(([id,title,detail])=>`<article><h3>${esc(title)}</h3>${detail?`<p class="muted">${esc(detail)}</p>`:''}${btn('Choisir','decision:'+id,'primary')}</article>`).join('')}</div>`}</section>`}

function liveMatch(){let m=s.match,events=s.mode==='key'?m.events.filter(e=>e.key).slice(-5):m.events.slice(-8);return `<section class="panel live"><p class="eyebrow">MATCH AUTOMATIQUE · ${s.mode==='key'?'MOMENTS CLÉS':'SUIVI DÉTAILLÉ'}${m.ot?' · PROLONGATION '+m.ot:''}</p><div class="scoreboard"><span>${esc(team(s,m.home).name)}</span><strong>${m.score[0]} <em>:</em> ${m.score[1]}</strong><span>${esc(team(s,m.away).name)}</span></div><p class="muted">${m.n} / ${m.total} possessions · les attributs, tendances et rotations déterminent le match.</p>${meter(m.n,m.total)}<div class="match-events">${events.map(e=>`<p><b>${e.score.join('–')}</b> ${esc(e.text)}</p>`).join('')||'<p>Le match commence. Les joueurs décident automatiquement.</p>'}</div><div class="button-row">${btn(s.mode==='key'?'Voir les prochains moments':'Voir la suite','watch','primary')}${btn('Afficher le résultat final','finish','secondary')}</div><p class="muted">Changer de présentation ne change ni les actions, ni le résultat.</p></section>`}

function summary(){let m=s.lastMatch,b=m.box[s.hero];return `<section class="panel"><div class="section-title"><h3>Dernier match</h3>${pill('Note '+grade(m.grade))}</div><div class="stat-strip">${[['Points',b.pts],['Rebonds',b.reb],['Passes',b.ast],['Minutes',b.min.toFixed(1)],['Tirs',b.fgm+'/'+b.fga],['3 points',b.tpm+'/'+b.tpa]].map(([l,v])=>`<div><strong>${v}</strong><span>${l}</span></div>`).join('')}</div><details><summary>Pourquoi cette note ? · Feuille de match</summary><p>${Object.entries(m.reasons).map(([k,v])=>`${esc(k)} : ${v>0?'+':''}${v.toFixed(1)}`).join(' · ')}</p>${boxTable(m.box)}</details></section>`}
function boxTable(box){return `<div class="table-scroll"><table><thead><tr><th>Joueur</th><th>MIN</th><th>PTS</th><th>REB</th><th>PD</th><th>Tirs</th><th>3 PTS</th><th>LF</th><th>INT</th><th>CTR</th><th>BP</th></tr></thead><tbody>${Object.values(box).map(b=>`<tr class="${b.id===s.hero?'you':''}"><td>${esc(b.name||s.players.find(p=>p.id===b.id)?.name)}</td><td>${b.min.toFixed(1)}</td><td>${b.pts}</td><td>${b.reb}</td><td>${b.ast}</td><td>${b.fgm}/${b.fga}</td><td>${b.tpm}/${b.tpa}</td><td>${b.ftm}/${b.fta}</td><td>${b.stl}</td><td>${b.blk}</td><td>${b.tov}</td></tr>`).join('')}</tbody></table></div>`}
function developmentReport(){let p=hero(s),d=s.development,year=d.year,previous=d.lastSeason;const changes=(start,end)=>Object.entries(GROUPS).map(([name,keys])=>{let delta=keys.reduce((n,k)=>n+(end[k]-start[k]),0)/keys.length;return `<span>${name} <b>${delta>=0?'+':''}${delta.toFixed(1)}</b></span>`}).join('');return `<section class="panel development-report"><h3>Votre évolution</h3><p class="muted">Depuis ${year?.season===s.season?'le début du suivi de cette saison':'la dernière mise à jour'} : ${fmt(year?.sources.match||0)} XP en match · ${fmt(year?.sources.training||0)} XP à l’entraînement.</p>${year?`<div class="development-changes">${changes(year.start,p.attrs)}</div>`:''}<p class="muted">Variation moyenne par attribut dans chaque domaine, après progression, âge et récupération.</p>${previous?`<details><summary>Bilan de la saison ${previous.season}</summary><div class="development-changes">${changes(previous.start,previous.end)}</div><p>${previous.gains} points améliorés · ${fmt(previous.sources.match)} XP en match · ${fmt(previous.sources.training)} XP à l’entraînement.</p>${Object.keys(previous.aging).length?`<p>Évolution liée à l’âge : ${Object.entries(previous.aging).map(([k,v])=>`${LABELS[k]} ${v>0?'+':''}${v}`).join(' · ')}.</p>`:''}</details>`:''}${p.age>=30?'<p>Conserver votre explosivité demande davantage d’XP avec l’âge. Le tir, les passes et le jeu au poste restent plus faciles à entretenir. Vous pouvez réorienter votre programme dans Carrière.</p>':''}</section>`}
function player(){let p=hero(s);return `<div class="tabs">${[['attrs','Attributs'],['badges','Badges'],['tech','Techniques'],['health','Profil & santé']].map(([id,t])=>btn(t,'sub:'+id,sub===id?'selected':'')).join('')}</div>${sub==='attrs'?`${developmentReport()}<p class="muted">Attributs de 25 à 99, sans plafond individuel. L’XP reste dans le domaine où elle est gagnée.</p><label class="check"><input id="auto" type="checkbox" ${s.auto?'checked':''}> Allouer automatiquement l’XP</label><div class="attribute-grid">${Object.entries(GROUPS).map(([g,ks])=>`<section class="panel"><div class="section-title"><h3>${g}</h3>${pill(Math.floor(s.development.xp[g])+' XP disponibles')}</div>${ks.map(k=>{let c=upgradeCost(p,k);return `<div class="attribute"><div><label>${LABELS[k]}</label><span><b>${Math.round(p.attrs[k])}</b> / 99</span>${meter(p.attrs[k],99)}</div>${btn('+1','upgrade:'+k,'small',p.attrs[k]>=99||s.development.xp[g]<c||!!s.match)}<small>${p.attrs[k]>=99?'Maximum commun atteint':`${fmt(c)} XP pour le prochain point${costDetails(p,k).ageFactor>=1.1?' · effort lié à l’âge ×'+costDetails(p,k).ageFactor.toFixed(1):''}`}</small></div>`}).join('')}</section>`).join('')}</div>${s.development.performance?`<section class="panel"><h3>XP du dernier match</h3><p>Efficacité ×${s.development.performance.efficiency} · ligue ×${s.development.performance.coefficient} · charge de matchs de la semaine ×${s.development.performance.normalizer}</p><p>${Object.entries(s.development.performance.amounts).map(([d,v])=>`${d} : +${v}`).join(' · ')}</p></section>`:''}`:sub==='badges'?`<p class="muted">Effet limité au contexte indiqué : +0,8 point de probabilité par niveau. Bonus cumulés plafonnés à 7 points.</p><div class="catalog">${BADGES.map(b=>{let lv=badgeLevel(p,b),xp=p.badges[b.id]||0;return `<article class="panel"><span class="badge-icon ${lv?'unlocked':''}">◇</span><h3>${b.name}</h3>${pill(LEVELS[lv])}<p>${b.description}</p><p class="muted">${lv?`Usage : ${xp} · Prochain palier à ${(Math.floor(xp/80)+1)*80} usages, sous réserve du niveau d’attribut.`:`Nécessite ${LABELS[b.attr]} ≥ ${b.threshold} (actuel ${p.attrs[b.attr]}).`}</p>${meter(xp%80,80)}</article>`}).join('')}</div>`:sub==='tech'?`<p class="muted">Apprenez puis équipez jusqu’à trois techniques. Le bonus ne s’applique qu’aux actions correspondantes. Désactivez l’allocation automatique d’XP pour en réserver à l’apprentissage.</p><div class="catalog">${TECHNIQUES.map(t=>`<article class="panel"><p class="eyebrow">${LABELS[t.attr]} ≥ ${t.threshold}</p><h3>${t.name}</h3><p>+${Math.round(t.effect*100)} points de réussite dans son contexte · effet contextuel plafonné.</p><p class="muted">${p.attrs[t.attr]<t.threshold?'Verrouillée : attribut insuffisant.':`Apprentissage : ${t.cost*25} XP du domaine ${domainOf(t.attr)}.`}</p>${p.learned.includes(t.id)?btn(p.equipped.includes(t.id)?'Équipée ✓':'Équiper','equip:'+t.id,'secondary'):btn('Apprendre','learn:'+t.id,'secondary',p.attrs[t.attr]<t.threshold||s.development.xp[domainOf(t.attr)]<t.cost*25)}</article>`).join('')}</div>`:`<section class="panel"><h2>${esc(p.name)}</h2><p>${p.age} ans · ${esc(p.nation)} · ${p.height} cm · ${p.weight} kg · Envergure ${p.wingspan} cm</p><p>Poste principal ${p.pos} · secondaire ${p.secondary} · ${p.style}</p><p class="muted">${esc(s.roleReason||'Le coach ajuste le rôle selon vos performances et la concurrence.')}</p>${btn('Demander un rôle plus important','role-request','secondary',!!s.pending||!!s.match)}<label>Tendances<select id="tendency-mode"><option value="auto" ${p.tendencyMode!=='manual'?'selected':''}>Automatiques selon mes compétences</option><option value="manual" ${p.tendencyMode==='manual'?'selected':''}>Personnalisées</option></select></label>${p.tendencyMode==='manual'?Object.entries(tendencies(p)).filter(([k])=>k!=='pass').map(([k,v])=>`<label>${{three:'Tir à trois points',drive:'Pénétration',post:'Jeu au poste',mid:'Mi-distance'}[k]}<input type="range" id="tendency-${k}" min="5" max="100" value="${v}"></label>`).join(''):''}<div class="metrics">${[['Fatigue',p.fatigue],['Charge cumulée',s.charge],['Lecture du jeu',s.iq],['Discipline',s.discipline],['Maîtrise du système',s.system],['Forme',s.form]].map(([l,v])=>`<article><span>${l}</span><strong>${Math.round(v)}</strong>${meter(v)}</article>`).join('')}</div><p>${p.injury?`Rééducation : encore ${p.injury} jours. Aucun match joué pendant l’indisponibilité.`:'Disponible. La récupération et la fatigue influencent vos performances.'}</p></section>`}`}
function career(){let p=hero(s),stage=s.career.stage;return `${pathway()}${ambitionPanel(s,true)}${reviewPanel(s,true)}${legacyPanel(s)}<details class="panel"><summary>Entraînement, rôle et contrat</summary><div class="two-col"><section class="panel"><p class="eyebrow">ENTRAÎNEMENT ASSISTÉ</p><h3>Votre programme</h3><label>Domaine prioritaire<select id="training-domain">${DOMAINS.map(d=>`<option ${s.trainingPlan.domain===d?'selected':''}>${d}</option>`).join('')}</select></label><label>Accompagnement<select id="training-mode"><option value="assisted" ${s.trainingPlan.mode==='assisted'?'selected':''}>Assisté · ajuste l’effort à la fatigue</option><option value="manual" ${s.trainingPlan.mode==='manual'?'selected':''}>Manuel · respecter mon intensité</option></select></label><label>Intensité<select id="training-intensity">${[['light','Légère'],['normal','Normale'],['hard','Soutenue']].map(([v,l])=>`<option value="${v}" ${s.trainingPlan.intensity===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Activité prioritaire<select id="activity">${[['individuel','Travail individuel'],['video','Vidéo et lecture du jeu'],['repos','Récupération'],['famille','Temps pour les proches'],...(stage!=='pro'?[['etudes','Études']]:[])].map(([v,l])=>`<option value="${v}" ${s.activity===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Compétence à privilégier<select id="training">${KEYS.map(k=>`<option value="${k}" ${s.training===k?'selected':''}>${LABELS[k]}</option>`).join('')}</select></label><p class="muted">Les séances suivent le calendrier, sans clic répétitif. L’entraînement et les performances alimentent les mêmes six domaines.</p><p>XP gagnée : <b>${fmt(s.development.sources.match)} en match</b> · <b>${fmt(s.development.sources.training)} à l’entraînement</b>.</p></section><section class="panel"><p class="eyebrow">${stage==='pro'?'CONTRAT & MOBILITÉ':'RECRUTEMENT & DRAFT'}</p><h3>${esc(team(s).name)}</h3>${stage==='pro'?`<h2>${fmt(p.contract.salary)} <small>€ / saison</small></h2><p>${p.contract.years} saison(s) restante(s) · option ${esc(p.contract.option)}</p>${btn('Demander à mon agent d’explorer le marché','trade','primary',!!s.match||!!s.pending||s.retired)}<p class="muted">Votre club peut refuser une demande. Les offres tiennent compte de votre niveau, du rôle et des besoins au poste.</p>`:`<p>Études : <b>${Math.round(s.career.academics)}/100</b> · exposition : <b>${Math.round(s.career.exposure)}/100</b></p><h3>${esc((s.lastSeasonScouting||scouting(s)).projection)}</h3><p class="muted">Lycée jusqu’à 18 ans, puis choix d’université. Après au moins une saison universitaire, vous choisissez quand tenter la draft. Les joueurs non draftés reçoivent des possibilités à l’étranger.</p>`}<hr><h3>${esc(s.role)} · ${s.minutes} minutes prévues</h3><p>${esc(s.roleReason||'Vos performances et la concurrence au poste déterminent votre rôle.')}</p>${btn('Demander davantage de responsabilités','role-request','secondary',!!s.pending||!!s.match)}<p class="muted">Le coach garde la décision finale.</p></section></div></details><section class="panel"><h3>Votre histoire</h3><details><summary>Palmarès · ${s.trophies.length} distinction(s)</summary><p>${s.trophies.map(esc).join(' · ')||'Les premiers trophées restent à gagner.'}</p></details><details><summary>Mes saisons · ${s.history.length}</summary>${s.history.map(h=>`<div class="fixture"><b>S${h.season}</b><span>${esc(h.team)} · ${esc(leagueDef(h.league)?.name||h.league)}<br>${h.stats.gp} matchs · ${h.stats.gp?(h.stats.pts/h.stats.gp).toFixed(1):0} points / match</span><b>${h.ovr} GÉN</b></div>`).join('')}</details><details><summary>Journal intégral · ${s.journal.length} événements</summary><label>Rechercher dans ma carrière<input id="journal-query" type="search" placeholder="Draft, blessure, champion…"></label><div id="journal-results">${journalRows(s.journal.slice(-35).reverse())}</div></details></section>${s.retired?`<section class="decision"><h2>Votre héritage</h2><p>${s.history.length} saisons · ${s.trophies.length} distinctions · ${fmt(netWorth(s))} € de patrimoine.</p><p>${s.life.children.length} enfant(s), ${s.life.partner?'une vie de couple':'une trajectoire personnelle libre'}. Les archives de votre carrière restent consultables.</p></section>`:''}`}
function journalRows(events){return events.map(e=>`<p><b>S${e.season} · ${esc(e.title)}</b><br>${esc(e.text)}</p>`).join('')||'<p>Aucun événement.</p>'}
function life(){let l=s.life;return `<section class="panel"><h2>Votre équilibre</h2><label class="check"><input id="life-delegate" type="checkbox" ${l.delegated?'checked':''}> Déléguer les choix courants à mon entourage</label><p class="muted">Les projets de famille et les décisions sportives importantes continuent d’arrêter la simulation.</p><div class="metrics">${[['Moral',l.morale],['Notoriété',l.fame],['Famille',l.family]].map(([label,v])=>`<article><span>${label}</span><strong>${Math.round(v)}</strong>${meter(v)}</article>`).join('')}</div><h3>${l.partner?'Votre couple':'Votre entourage'}</h3><p>${l.partner?`Relation depuis la saison ${Math.floor(l.partner.since/365)+1} · complicité ${Math.round(l.partner.bond)}/100`:'Une rencontre peut ouvrir un nouveau chapitre à partir de 18 ans.'}</p>${l.expecting?`<p class="orange">Un enfant attendu dans environ ${Math.ceil((l.expecting-s.day)/30)} mois.</p>`:''}<p>${l.children.length?l.children.map(c=>`Enfant ${c.id.split('-')[1]} · ${Math.floor((s.day-c.born)/365)} ans`).join(' · '):'Pas d’enfant.'}</p><div class="stat-strip">${Object.entries(s.relationships).map(([k,v])=>`<div><strong>${Math.round(v)}</strong><span>${{coach:'Coach',team:'Coéquipiers',agent:'Agent',mentor:'Mentor',family:'Proches'}[k]}</span></div>`).join('')}</div></section><div class="two-col"><section class="panel"><h3>Finances personnelles</h3><div class="focus-stat"><strong>${fmt(netWorth(s))}</strong><span>€ de patrimoine</span></div><p>Disponible : <b>${fmt(s.money)} €</b><br>Placements : <b>${fmt(l.investments)} €</b><br>Résidence : <b>${l.property?fmt(l.property.value)+' € · '+esc(l.property.city):'Aucune'}</b></p><label>Train de vie<select id="lifestyle">${[['simple','Simple'],['comfortable','Confortable'],['premium','Premium']].map(([id,label])=>`<option value="${id}" ${l.lifestyle===id?'selected':''}>${label}</option>`).join('')}</select></label><div class="button-row">${btn('Placer 20 % du disponible','life:invest','secondary',s.money<2500||!!s.match||!!s.pending)}${btn('Retirer des placements','life:withdraw','secondary',!l.investments||!!s.match||!!s.pending)}${btn('Acheter une résidence · 250 000 €','life:property','secondary',s.money<250000||!!l.property||!!s.match||!!s.pending)}</div><p class="muted">Valeurs simplifiées de jeu. Les placements peuvent baisser. Les versements nets représentent 76 % du salaire brut ; les dépenses suivent votre train de vie.</p><details><summary>Derniers mouvements</summary>${l.ledger.map(e=>`<p>J${e.day} · ${esc(e.label)} : ${fmt(e.amount)} €</p>`).join('')||'<p>Pas encore de mouvement.</p>'}</details></section><section class="panel"><h3>Sponsors & médias</h3>${l.sponsors.map(c=>`<h4>${esc(c.name)}</h4><p>${fmt(c.annual)} € / an · ${Math.ceil((c.ends-s.day)/365)} an(s) restant(s)</p>`).join('')||'<p>Les marques s’intéresseront à vous lorsque votre carrière professionnelle et votre notoriété se développeront.</p>'}<p class="muted">Les propositions et interviews naissent de votre carrière. Vous choisissez votre exposition et le temps donné à votre entourage.</p></section></div>`}

function league(){let lid=leagueSelection||s.league,def=leagueDef(lid),c=competition(s,lid),rank=standings(s,lid),club=selectedTeam&&def.teams.includes(team(s,selectedTeam)?.name)?team(s,selectedTeam):rank[0],archive=s.archives.find(a=>a.season===Number(archiveSeason)),ac=archive?.competitions?.find(c=>c.id===lid);let games=ac?ac.games:c.schedule;return `<section class="league-heading"><label>Championnat<select id="league-select">${LEAGUES.map(l=>`<option value="${l.id}" ${lid===l.id?'selected':''}>${esc(l.name)} · ${l.games} matchs</option>`).join('')}</select></label><div><h2>${esc(def.name)}</h2><p>${def.teams.length} équipes · ${def.games} matchs réguliers · ${def.minutes} minutes</p>${pill(def.country)} ${pill(c.phase)}</div></section><p class="muted">NBA : identités réelles au départ, nouvelles générations fictives · Référence ${REFERENCE.season}. ${def.note||'Calendrier, évaluations et contrats simulés. Autres ligues : joueurs fictifs.'}</p><div class="tabs">${['Classement','Calendrier','Équipes','Statistiques','Draft & marché'].map(v=>btn(v,'league:'+v,v===leagueView?'selected':'')).join('')}</div><section class="panel">${leagueView==='Classement'?`<div class="table-scroll"><table><thead><tr><th>#</th><th>Équipe</th><th>V</th><th>D</th><th>Diff.</th>${lid==='nba'?'<th>Conférence</th>':''}</tr></thead><tbody>${rank.map((t,i)=>`<tr class="${t.id===s.team?'you':''}"><td>${i+1}</td><td>${btn(esc(t.name)+(t.id===s.team?' · VOUS':''),'team:'+t.id,'link')}</td><td>${t.wins}</td><td>${t.losses}</td><td>${t.for-t.against}</td>${lid==='nba'?`<td>${t.conference}</td>`:''}</tr>`).join('')}</tbody></table></div><p class="muted">Classement de saison régulière uniquement. ${def.playIn?'Play-in puis ':''}${def.playoff} équipes en phases finales. ${lid==='nba'?'Huit qualifiés par conférence, séries au meilleur des sept matchs.':lid==='euroleague'?'Quarts au meilleur des cinq matchs, puis Final Four.':''}</p>${c.champion?`<h3>Champion : ${esc(team(s,c.champion).name)}</h3>`:''}`:leagueView==='Calendrier'?`<label>Saison<select id="calendar-season"><option value="">Saison actuelle</option>${s.archives.map(a=>`<option value="${a.season}" ${a.season===Number(archiveSeason)?'selected':''}>Saison ${a.season}</option>`).join('')}</select></label><label>Équipe<select id="calendar-team">${rank.map(t=>`<option value="${t.id}" ${t.id===(selectedTeam|| (rank.some(t=>t.id===s.team)?s.team:club.id))?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label>${games.filter(g=>g.home===(selectedTeam||(rank.some(t=>t.id===s.team)?s.team:club.id))||g.away===(selectedTeam||(rank.some(t=>t.id===s.team)?s.team:club.id))).sort((a,b)=>a.day-b.day).map(g=>`<div class="fixture"><span>J${g.day-((archive?.season||s.season)-1)*365}<br>${g.stage==='regular'?'Saison':g.stage==='playin'?'Play-in':'Playoffs'}</span><span>${esc(team(s,g.home).name)}<br>${esc(team(s,g.away).name)}</span><b>${g.score?g.score.join(' – '):g.result?g.result.score.join(' – '):'À venir'}</b></div>`).join('')}`:leagueView==='Équipes'?`<label>Équipe<select id="team-select">${rank.map(t=>`<option value="${t.id}" ${t.id===club.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><h3>${esc(club.name)}</h3><p>Compétitions : ${club.competitions.map(id=>leagueDef(id).name).join(' + ')}</p><p class="muted">Un seul effectif partagé entre championnat national et EuroLeague.</p><div class="table-scroll"><table><thead><tr><th>Joueur</th><th>Poste</th><th>Âge</th><th>Général</th><th>Contrat</th></tr></thead><tbody>${club.roster.map(id=>{let p=s.players.find(q=>q.id===id);return `<tr class="${id===s.hero?'you':''}"><td>${esc(p.name)} ${p.injury?'✚':''}</td><td>${p.pos}</td><td>${p.age}${p.ageEstimated?' ≈':''}</td><td>${overall(p)}</td><td>${p.contract.years} ans</td></tr>`}).join('')}</tbody></table></div>`:leagueView==='Statistiques'?`<div class="table-scroll"><table><thead><tr><th>Joueur</th><th>MJ</th><th>PTS</th><th>REB</th><th>PD</th></tr></thead><tbody>${s.players.filter(p=>p.byLeague[lid]?.gp).sort((a,b)=>b.byLeague[lid].pts/b.byLeague[lid].gp-a.byLeague[lid].pts/a.byLeague[lid].gp).slice(0,50).map(p=>{let st=p.byLeague[lid];return `<tr class="${p.id===s.hero?'you':''}"><td>${esc(p.name)}</td><td>${st.gp}</td><td>${(st.pts/st.gp).toFixed(1)}</td><td>${(st.reb/st.gp).toFixed(1)}</td><td>${(st.ast/st.gp).toFixed(1)}</td></tr>`}).join('')}</tbody></table></div><p class="muted">Moyennes dans cette compétition, phases finales comprises.</p>`:`<h3>Draft NBA & mobilité internationale</h3><p>${s.draftResult?s.draftResult.rank?'Vous avez été sélectionné en position '+s.draftResult.rank+'.':'Vous n’avez pas été drafté. La progression à l’étranger peut ouvrir la NBA.':'La draft se prépare au lycée puis à l’université. Votre rang dépend du niveau, de l’efficacité, des performances et de la promotion concurrente.'}</p><p class="muted">Les transferts conservent le même joueur. Le club quitté recrute un remplaçant ; le club d’arrivée ajuste son effectif. Les matchs déjà joués restent inchangés.</p>${(s.lastDraft||[]).slice(0,20).map(p=>`<div class="fixture"><span>${esc(p.name)} · ${p.pos}</span><span>${esc(p.team)}</span><b>${p.ovr}</b></div>`).join('')}${s.log.filter(e=>['Contrat signé','Draft NBA','Transfert refusé'].includes(e.title)).slice(0,8).map(e=>`<p><b>${esc(e.title)}</b><br>${esc(e.text)}</p>`).join('')}`}</section>`}
function more(){return `<p class="eyebrow">HOOP LEGACY · VERSION ${VERSION}</p><div class="two-col"><section class="panel"><h3>Sauvegardes</h3><p class="muted">Sauvegarde automatique après chaque action, sur cet appareil. Exportez une copie pour changer de téléphone.</p><div class="button-row">${btn('Exporter en JSON','export','primary')}<label class="button secondary">Importer un JSON<input class="sr" type="file" id="import" accept=".json,application/json"></label></div>${[1,2,3].map(i=>`<div class="fixture"><span>Emplacement ${i}</span>${btn('Sauver','save:'+i,'small')}${btn('Charger','load:'+i,'small')}</div>`).join('')}<p class="muted">Une sauvegarde valide reste intacte si l’import échoue.</p>${btn('Restaurer le dernier autosave de secours','load:rollback','secondary')}</section><section class="panel"><h3>Réglages de match</h3><label>Présentation<select id="mode">${[['quick','Simulation rapide'],['key','Moments clés'],['detail','Suivi détaillé']].map(([k,l])=>`<option value="${k}" ${s.mode===k?'selected':''}>${l}</option>`).join('')}</select></label><p class="muted">Un seul moteur pour les trois modes. Les longues avances sont simulées rapidement ; les matchs individuels suivent votre mode préféré.</p><h3>Installer sur téléphone</h3>${installPrompt?btn('Installer HOOP LEGACY','install','secondary'):'<p class="muted">iPhone : dans Safari, Partager → Sur l’écran d’accueil. Android : menu du navigateur → Installer l’application, si proposé. Chargez une première fois avant de jouer hors ligne.</p>'}${btn('Créer une autre carrière','new','secondary')} ${btn('Prendre ma retraite','retire','secondary',s.retired||!!s.match||!!s.pending)}</section></div><section class="panel"><h3>Palmarès & saisons</h3>${s.legacyArchive?`<p class="muted">Ancienne carrière conservée : ${esc(s.legacyArchive.team)} · ${s.legacyArchive.stats.gp} matchs.</p>${btn('Exporter l’archive de mon ancienne saison','export-legacy','secondary')}`:''}<div class="stat-strip">${[['Points',s.records?.pts||0],['Rebonds',s.records?.reb||0],['Passes',s.records?.ast||0]].map(([l,n])=>`<div><strong>${n}</strong><span>Record · ${l}</span></div>`).join('')}</div><p>${s.trophies.map(esc).join(' · ')||'Votre palmarès reste à écrire.'}</p><details><summary>Mes saisons · ${s.history.length}</summary>${s.history.map(h=>`<div class="fixture"><b>Saison ${h.season}</b><span>${esc(h.team)}<br>${h.stats.gp} matchs · ${h.stats.gp?(h.stats.pts/h.stats.gp).toFixed(1):0} points / match</span><span>Champion : ${esc(h.champion)}<br>MVP : ${esc(h.mvp)}</span></div>`).join('')||'<p class="muted">Votre première saison apparaîtra ici après les récompenses.</p>'}</section><section class="panel"><details><summary>Aide, règles & limites de cette version</summary><p>MJ : meneur (dans un profil) ou matchs joués (statistiques). AR : arrière. AI : ailier. AF : ailier fort. P : pivot. PTS : points. REB : rebonds. PD : passes décisives. LF : lancers francs. INT : interceptions. CTR : contres. BP : balles perdues. MIN : minutes.</p><p>Les notes vont de 25 à 99, sans correspondre à un pourcentage de réussite. La note générale est pondérée par poste ; la fatigue, le contexte défensif et les tendances interviennent séparément.</p><p>Formats de référence 2025–26 : NBA 82, EuroLeague 38, France 30, Espagne 34, Allemagne 34, Italie 30, NBL 33. Effectifs NBA du 21 octobre 2025 pour les nouvelles parties, autres joueurs fictifs. Notes, salaires et certains âges sont estimés pour le jeu. NCAA : sélection de 32 programmes, 31 matchs simulés ; lycée : circuit fictif de 24 matchs. Les calendriers scolaires réels varient. Les règles financières et les transferts restent simplifiés ; les promotions/relégations nationales et les coupes ne sont pas simulées.</p><p>Les attributs, badges et techniques modifient les probabilités contextuelles. Le tir dépend de la compétence, de la contestation et de la fatigue. Les matchs sont entièrement automatiques. Aucun Takeover ni bonus de commande manuelle.</p><p>Version ${VERSION} · Pack mondial 2025–26 · Sauvegarde schéma 4.</p></details></section>`}
const steps=['Identité','Départ','Parcours','Mensurations','Poste','Style','Validation'];
function field(label,id,value,type='text',extra=''){return `<label>${label}<input id="${id}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function renderCreation(){let l=limits(build);let content=[`${field('Nom du joueur','b-name',build.name,'text','maxlength="35"')}<label>Mode de création<select id="b-mode"><option value="custom">Personnalisé</option><option value="random">Aléatoire</option><option value="hybrid">Hybride : physique aléatoire, style libre</option></select></label>`,`${field('Âge','b-age',build.age,'number','min="16" max="25"')}<label>Point de départ<select id="b-path">${[['young','Lycée · 16–17 ans → recrutement universitaire'],['prospect','Université · une à quatre saisons avant la draft'],['rookie','Rookie NBA · commencer directement en pro']].map(([v,t])=>`<option value="${v}" ${build.path===v?'selected':''}>${t}</option>`).join('')}</select></label>`,`${field('Nationalité / origine','b-nation',build.nation,'text','maxlength="60"')}<p class="muted">Votre origine fait partie de votre identité. Elle ne donne aucun bonus sportif automatique.</p>`,`${field('Taille (cm)','b-height',build.height,'number','min="175" max="225"')}${field('Poids (kg)','b-weight',build.weight,'number','min="65" max="140"')}${field('Envergure (cm)','b-wingspan',build.wingspan,'number','min="175" max="240"')}`,`<label>Poste principal<select id="b-pos">${['MJ','AR','AI','AF','P'].map(v=>`<option ${build.pos===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Poste secondaire<select id="b-secondary">${['MJ','AR','AI','AF','P'].map(v=>`<option ${build.secondary===v?'selected':''}>${v}</option>`).join('')}</select></label><p class="muted">MJ : meneur · AR : arrière · AI : ailier · AF : ailier fort · P : pivot.</p>`,`<div class="style-options">${Object.keys(STYLES).map(v=>btn(v,'style:'+v,build.style===v?'selected':'secondary')).join('')}</div><p class="muted">Ce choix oriente vos compétences de départ, sans verrouiller votre carrière.</p>`,`<p class="eyebrow">${esc(build.style).toUpperCase()} / ${build.pos}</p><h2>${esc(build.name)}</h2><p>${build.age} ans · ${esc(build.nation)}<br>${build.height} cm · ${build.weight} kg · Envergure ${build.wingspan} cm</p><p>Points forts : ${STYLES[build.style].map(k=>LABELS[k]).join(', ')||'profil équilibré'}</p><p>À développer : ${KEYS.filter(k=>!STYLES[build.style].includes(k)).slice(0,4).map(k=>LABELS[k]).join(', ')}</p><p>${build.path==='young'?'Lycée : des saisons complètes, puis choix d’université.':build.path==='prospect'?'Université : progressez, puis choisissez quand tenter la draft.':'NBA : 82 matchs de saison régulière et concurrence professionnelle.'}</p><p class="muted">${BADGES.filter(b=>build.caps[b.attr]>=b.threshold).length} badges et ${TECHNIQUES.filter(t=>build.caps[t.attr]>=t.threshold).length} techniques accessibles à terme. Chaque attribut pourra progresser jusqu’à 99 avec de l’XP, sans plafond individuel.</p>`][step];$('app').innerHTML=header()+`<main class="creation"><div class="creation-heading"><p class="eyebrow">NOUVELLE CARRIÈRE / ${String(step+1).padStart(2,'0')} — 07</p><h1>Chaque légende<br>commence quelque part<span class="orange">.</span></h1><p class="muted">Créez le joueur. Écrivez la suite sur le terrain.</p></div><section class="creator panel"><div class="step-track">${steps.map((t,i)=>`<span class="${i<=step?'on':''}" title="${t}"></span>`).join('')}</div><p class="eyebrow">ÉTAPE ${step+1}</p><h2>${steps[step]}</h2>${content}<div class="creator-footer">${btn('← Retour','prev','secondary',step===0)}${btn(step===6?'Entrer dans la ligue →':'Continuer →',step===6?'create':'next-step','primary')}</div>${s?btn('Revenir à ma carrière','cancel-new','link'):''}<hr><label class="button secondary">Importer une carrière<input class="sr" type="file" id="import" accept=".json,application/json"></label></section><p class="creation-note">Ligues réelles · Effectifs NBA de référence · Sauvegarde sur votre appareil</p></main>`;bind()}
function readBuild(){for(let k of ['name','age','nation','path','height','weight','wingspan','pos','secondary']){let el=$('b-'+k);if(el)build[k]=['age','height','weight','wingspan'].includes(k)?Number(el.value):el.value.trim()}if(!build.name)build.name='Joueur';build.age=Math.min(25,Math.max(16,build.age||19));build.height=Math.min(225,Math.max(175,build.height||195));build.weight=Math.min(140,Math.max(65,build.weight||88));build.wingspan=Math.min(240,Math.max(175,build.wingspan||202));if(step===1)build.age=build.path==='young'?Math.min(17,Math.max(16,build.age)):build.path==='prospect'?Math.min(21,Math.max(18,build.age)):Math.max(19,build.age);if(step===3)build.caps=buildCaps(build);if(step===0&&$('b-mode')?.value!=='custom'){let a=new Uint32Array(4);crypto.getRandomValues(a);build.seed=a[0]||1;build.height=180+a[1]%36;build.weight=75+a[2]%41;build.wingspan=build.height+5+a[3]%12;if($('b-mode').value==='random'){build.style=Object.keys(STYLES)[a[0]%5];build.pos=['MJ','AR','AI','AF','P'][a[1]%5]}build.caps=buildCaps(build)}}
async function action(a){if(busy&&!['stop'].includes(a)&&!a.startsWith('tab:'))return;let [act,arg]=a.split(':');if(act==='tab'){tab=arg;render();return}if(act==='sub'){sub=arg;render();return}if(act==='league'){leagueView=arg;render();return}if(act==='team'){selectedTeam=arg;leagueView='Équipes';render();return}if(act==='prev'){readBuild();step--;render();return}if(act==='next-step'){readBuild();if(step===6&&potentialCost(build.caps)>CFG.budget){toast('Réduisez le potentiel pour respecter le budget.');return}step++;render();return}if(act==='style'){build.style=arg;build.caps=buildCaps(build);render();return}if(act==='create'){s=createGame(build);creation=false;step=0;await persist();render();return}if(act==='cancel-new'){creation=false;render();return}if(act==='new'){if(confirm('Votre partie actuelle sera conservée en emplacement 3. Créer un autre joueur ?')){await save(s,'slot3');build=defaultBuild();step=0;creation=true;render()}return}
if(act==='advance'){let val=$('advance-size').value;if(val==='1'){busy=true;next(s);busy=false}else if(val==='match'){busy=true;let n=0,last=s.lastMatch?.id;do{next(s);n++}while(!s.match&&!s.pending&&!s.retired&&s.lastMatch?.id===last&&n<20);busy=false}else{busy=true;progress=0;archivePrefix=s.archives.slice(0,-1);worker=new Worker('./worker.js?v=3.2.0',{type:'module'});worker.onmessage=async e=>{if(e.data.type==='progress'){progress=e.data.value;s={...e.data.state,archives:[...archivePrefix,...e.data.state.archives]};await persist();render()}else if(e.data.type==='done'){s={...e.data.state,archives:[...archivePrefix,...e.data.state.archives]};busy=false;worker.terminate();worker=null;await persist();render()}else{if(e.data.state)s={...e.data.state,archives:[...archivePrefix,...e.data.state.archives]};busy=false;toast(e.data.message);worker.terminate();worker=null;await persist();render()}};worker.onerror=()=>{busy=false;toast('Simulation interrompue ; votre partie précédente est conservée.');worker?.terminate();render()};worker.postMessage({state:{...s,archives:s.archives.slice(-1)},steps:val==='40'?400:val==='2'?8:Number(val),targetSeason:val==='40'?s.season+1:null,targetDay:val==='2'?s.day+7:null});render();return}}if(act==='stop'){worker?.postMessage({type:'stop'});return}if(act==='watch')continueMatch(s,null,s.mode==='detail'?10:40);if(act==='finish')continueMatch(s,null,10000);if(act==='life')lifeAction(s,arg);if(act==='role-request'){if(s.day-(s.lastRoleRequest??-100)<21){toast('Laissez trois semaines au coach pour évaluer vos performances.');return;}s.lastRoleRequest=s.day;log(s,'Discussion avec le coach',s.trust>=60?'Vos performances justifient une réévaluation lors des prochains matchs.':'Le coach attend une série plus convaincante avant de modifier votre rôle.');s.pending={type:'sport',title:'Réponse du coach',text:s.roleReason||'Votre rôle sera évalué selon vos prochaines performances.',choices:[['accept','Continuer à travailler']]};}if(act==='upgrade'){if(!upgrade(s,arg))toast('Pas assez de points ou plafond atteint.')}if(act==='learn'){if(!learn(s,arg))toast('Prérequis ou points insuffisants.')}if(act==='equip')equip(s,arg);if(act==='sign'){sign(s,Number(arg));leagueSelection=null;selectedTeam=null;}if(act==='decision')decide(s,arg);if(act==='trade')requestTrade(s);if(act==='relation'){let old=s.activity;s.activity='entourage';s.relationTarget=arg;next(s);s.activity=old;}if(act==='retire'&&confirm('Terminer définitivement cette carrière ?')){s.retired=true;log(s,'Retraite',`${hero(s).name} quitte les parquets. Votre histoire reste consultable.`)}if(act==='export-legacy'){let url=URL.createObjectURL(new Blob([JSON.stringify(s.legacyArchive)],{type:'application/json'}));let a=document.createElement('a');a.href=url;a.download='hoop-legacy-ancienne-saison.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return}if(act==='export'){let url=URL.createObjectURL(new Blob([JSON.stringify(s)],{type:'application/json'}));let a=document.createElement('a');a.href=url;a.download='hoop-legacy-saison-'+s.season+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return}if(act==='save'){await save(s,'slot'+arg);toast('Emplacement '+arg+' sauvegardé.')}if(act==='load'){let data=await load(arg==='rollback'?'rollback':'slot'+arg);if(!data){toast('Cet emplacement est vide.');return}if(confirm('Charger cet emplacement ? La partie actuelle sera gardée en secours.')){await save(s,'before-load');s=data}}if(act==='install'){await installPrompt?.prompt();installPrompt=null}await persist();render()}
function bind(){if($('season-ambition'))$('season-ambition').onchange=async e=>{if(busy||acting)return;if(chooseAmbition(s,e.target.value)){await persist();render()}};if(busy||acting)document.querySelectorAll('main button,main select,main input').forEach(el=>{if(el.dataset.action!=='stop')el.disabled=true});document.querySelectorAll('[data-action]').forEach(el=>el.onclick=async()=>{if(acting)return;acting=true;document.querySelectorAll('main button,main select,main input').forEach(control=>control.disabled=true);try{await action(el.dataset.action)}catch(e){busy=false;toast(e.message);render()}finally{acting=false;render()}});document.querySelector('.brand')?.addEventListener('click',e=>{e.preventDefault();tab='home';render()});for(let k of KEYS){let el=$('cap-'+k);if(el)el.oninput=()=>{build.caps[k]=Number(el.value);$('v-'+k).textContent=el.value;$('budget').textContent=Math.round(potentialCost(build.caps))}}for(let k of ['training','activity','mode'])if($(k))$(k).onchange=async e=>{s[k]=e.target.value;await persist()};for(let [id,object,key] of [['training-domain',s?.trainingPlan,'domain'],['training-mode',s?.trainingPlan,'mode'],['training-intensity',s?.trainingPlan,'intensity'],['lifestyle',s?.life,'lifestyle'],['tendency-mode',s?hero(s):null,'tendencyMode']])if($(id))$(id).onchange=async e=>{if(s.match||busy)return;object[key]=e.target.value;await persist();render()};if($('life-delegate'))$('life-delegate').onchange=async e=>{s.life.delegated=e.target.checked;await persist()};for(let k of ['three','drive','post','mid'])if($('tendency-'+k))$('tendency-'+k).onchange=async e=>{if(s.match||busy)return;hero(s).tendencies??={};hero(s).tendencies[k]=Math.max(5,Math.min(100,Number(e.target.value)));await persist()};if($('journal-query'))$('journal-query').oninput=e=>{$('journal-results').innerHTML=journalRows(s.journal.filter(v=>(v.title+' '+v.text).toLocaleLowerCase().includes(e.target.value.toLocaleLowerCase())).slice(-60).reverse())};if($('auto'))$('auto').onchange=async e=>{s.auto=e.target.checked;await persist()};if($('league-select'))$('league-select').onchange=e=>{leagueSelection=e.target.value;selectedTeam=null;archiveSeason=null;render()};if($('calendar-team'))$('calendar-team').onchange=e=>{selectedTeam=e.target.value;render()};if($('calendar-season'))$('calendar-season').onchange=e=>{archiveSeason=e.target.value;render()};if($('team-select'))$('team-select').onchange=e=>{selectedTeam=e.target.value;render()};if($('import'))$('import').onchange=async e=>{try{let file=e.target.files[0];if(!file)return;let data=parseSave(await file.text());await save(s,'before-import');s=data;await persist();toast('Partie importée.');render()}catch(e){toast('Import refusé : '+e.message)}}}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});
try{s=await load();notice=s?'Sauvegarde retrouvée':''}catch(e){try{s=await load('rollback');if(s){await save(s,'recovery-copy');notice='Copie de secours retrouvée';toast('La dernière copie valide a été retrouvée. Exportez-la depuis le menu ☰.');}else toast('Impossible de lire la sauvegarde : '+e.message);}catch{toast('Sauvegarde illisible. Vous pouvez importer votre export JSON.');}}render();
const hadController=!!navigator.serviceWorker?.controller;
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js?v=3.2.0').then(r=>{r.update();navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!busy&&hadController)toast('Version 3.2 disponible. Fermez puis rouvrez le jeu pour l’utiliser.');});}).catch(()=>toast('Mode hors ligne indisponible dans ce navigateur.'));
